import { v5, v7, validate } from "uuid";

/** New UUID v7 — time-ordered, generated by the application (never by the database). */
export const newId = (): string => v7();

export const isId = (value: unknown): value is string => typeof value === "string" && validate(value);

/** Settings have text keys; their events need a stable id. Same key, same id, always (UUID v5). */
const SETTINGS_NAMESPACE = "6f0e3a4c-2b1d-4c8e-9a7f-0d5b3e2c1a90";
export const settingId = (key: string): string => v5(key, SETTINGS_NAMESPACE);
